% Per-graph legend overrides loaded from the TSV generated by the Tcl GUI.
% GX-TXT Pipeline v0.3.8 - header-driven parser for backward compatibility.
% Copyright (C) 2026 Giuseppe Lanzani / giux-lab.it
function o = gxtxt_plot_legend_override(graphKey)
  o = struct();
  if (nargin < 1 || isempty(strtrim(graphKey))), return; endif
  path = strtrim(getenv('GXTXT_PLOT_LEGEND_OVERRIDE_FILE'));
  if (isempty(path) || exist(path,'file') != 2), return; endif
  fid = fopen(path,'r');
  if (fid < 0), return; endif
  cleaner = onCleanup(@() fclose(fid));

  headerLine = fgetl(fid);
  if (!ischar(headerLine)), return; endif
  headers = regexp(headerLine,'\t','split');
  for k=1:numel(headers), headers{k}=lower(strtrim(headers{k})); endfor

  while (true)
    line = fgetl(fid);
    if (!ischar(line)), break; endif
    parts = regexp(line,'\t','split');
    if (isempty(parts)), continue; endif
    if (!strcmp(strtrim(parts{1}),graphKey)), continue; endif

    enabled = field_value(headers,parts,'enabled');
    if (!isempty(enabled))
      v = str2double(enabled);
      if (isfinite(v) && v == 0), return; endif
    endif

    fields = {'mode','placement','location','alignment','orientation','layout','columns','background','border','border_color','font_unit','font_size','external_margin_px','manual_x','manual_y'};
    for k=1:numel(fields)
      v = field_value(headers,parts,fields{k});
      if (!isempty(v)), o.(fields{k}) = v; endif
    endfor
    return;
  endwhile
endfunction

function v = field_value(headers,parts,name)
  v = '';
  idx = find(strcmp(headers,name),1);
  if (isempty(idx) || idx > numel(parts)), return; endif
  v = strtrim(parts{idx});
endfunction
